// IsNonNamingChar 判断单字是否为「不适合入名」的质量门禁字
// 用于候选池阶段硬剔除：伙/腕/膨/仲/之/六 等任何语境下都无命名价值的字
func IsNonNamingChar(char string) bool {
	if char == "" {
		return false
	}
	return nonNamingChars[char]
}